<script setup>
import{onMounted,ref}from'vue';import{useRouter}from'vue-router';import{api}from'../api';import{IonPage,IonContent,IonButton}from'@ionic/vue';
const user=JSON.parse(localStorage.getItem('driverUser')||'{}'),router=useRouter(),requests=ref([]),form=ref({type:'LEAVE',start:'',end:'',reason:''}),document=ref(null),busy=ref(false);
async function load(){requests.value=(await api.get('/driver/availability')).data}onMounted(load);function out(){localStorage.removeItem('driverToken');localStorage.removeItem('driverUser');router.replace('/driver/login')}function pick(e){document.value=e.target.files?.[0]||null}
async function submit(){if(!form.value.start)return alert('Start date is required.');const f=new FormData();Object.entries(form.value).forEach(([k,v])=>f.append(k,v||''));if(document.value)f.append('document',document.value);busy.value=true;try{await api.post('/driver/availability',f);form.value={type:'LEAVE',start:'',end:'',reason:''};document.value=null;await load()}finally{busy.value=false}}
</script><template><ion-page><ion-content><div class="mob-hero"><small>ACCOUNT & AVAILABILITY</small><h1>{{user.name}}</h1><p>{{user.role?.replaceAll('_',' ')}}</p></div><div class="scanbox"><b>Leave / medical leave</b><p class="profile-help">Submit availability early where possible. Medical certificates can be photographed or uploaded. Route replacement remains subject to manager approval.</p><label>Type</label><select v-model="form.type"><option value="LEAVE">Annual leave</option><option value="MEDICAL_LEAVE">Medical leave</option><option value="DAY_OFF">Day off</option><option value="UNAVAILABLE">Unavailable</option></select><label>From</label><input type="date" v-model="form.start"/><label>To</label><input type="date" v-model="form.end"/><label>Reason / notes</label><textarea rows="3" v-model="form.reason"></textarea><label>Medical certificate / document</label><input type="file" accept="image/*,.pdf" capture="environment" @change="pick"/><ion-button expand="block" :disabled="busy" @click="submit">Submit request</ion-button></div><div class="scanbox"><b>My requests</b><div v-if="!requests.length" class="schedule-empty">No requests.</div><div v-for="r in requests" :key="r.id" class="availability-row"><div><b>{{r.type.replaceAll('_',' ')}}</b><small>{{r.start}} → {{r.end||r.start}}</small></div><span class="pillm">{{r.status}}</span></div></div><div class="scanbox"><b>Role-based mobile access</b><p class="profile-help">The driver app focuses on schedule, route navigation, handoff proof, incidents and availability. Detailed administration stays on the operations portal.</p><a class="portal-return portal-return-card" href="/login"><span aria-hidden="true">←</span> Back to FlowDepot login</a><ion-button expand="block" fill="outline" @click="out">Sign out</ion-button></div></ion-content></ion-page></template>
